import bisect
import csv
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FUNCS_DIR = os.path.join(ROOT, "funcs")
SNIFFER_ROOT = os.path.normpath(os.path.join(ROOT, "..", "ssbu-call-sniffer"))
OUT_DIR = os.path.join(SNIFFER_ROOT, "src", "hooks")

IDENT_RE = re.compile(r"[^A-Za-z0-9_]+")
IMAGE_BASE = 0x7100000000

PRELUDE = """// Auto-generated by ssbu-xref-db/scripts/generate_hooks.py from ssbu-xref-db/{src}
// Do not edit manually. Re-run the script to refresh

use crate::logger;

"""
# Virtual categories take precedence over search categories of the same name
VIRTUAL_SOURCES = {
    "hash40": "tables/hash40_loads.csv",
    "runtime": "tables/runtime_xrefs.csv",
}


def safe_ident(name, fallback):
    n = IDENT_RE.sub("_", name).strip("_")
    if not n or n[0].isdigit():
        n = "_" + n
    if not n:
        n = fallback
    return n[:80].lower()


def parse_offset(s):
    s = (s or "").strip().lower()
    if not s:
        return None
    if s.startswith("0x"):
        s = s[2:]
    try:
        return int(s, 16)
    except ValueError:
        return None


def to_int(s, default=0):
    try:
        return int((s or "").strip())
    except ValueError:
        return default


def pick_name(row):
    if (row.get("Function Symbol") or "").strip().startswith("_Z"):
        dm = (row.get("Function Demangled") or "").strip()
        if dm:
            return dm
    ext = [e.strip().rpartition("@") for e in (row.get("External Names") or "").split(";")]
    for name, _, label in ext:
        if label.startswith("curated") and name:
            return name
    fn = (row.get("Function Name") or "").strip()
    if fn and not is_placeholder(fn):
        return fn
    for name, _, label in ext:
        if label.startswith("ssbu-decomp") and name and not is_placeholder(name):
            return name
    return (row.get("Suggested Name") or "").strip()


def is_placeholder(name):
    return name.split("::")[-1].removeprefix("thunk_").startswith("FUN_")


def load_funcs_all_index():
    path = os.path.join(FUNCS_DIR, "funcs_all.csv")
    by_off = {}
    if not os.path.isfile(path):
        return by_off
    with open(path, "r", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            off = parse_offset(row.get("Function Offset"))
            if off is not None:
                by_off[off] = row
    return by_off


class FunctionTable:
    def __init__(self, path):
        self.ranges = []
        self.info = {}
        with open(path, "r", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                entry = parse_offset(row.get("Offset"))
                if entry is None:
                    continue
                self.info[entry] = (to_int(row.get("Size")), (row.get("Name") or "").strip())
                for part in (row.get("Ranges") or "").split(";"):
                    lo, _, hi = part.partition("-")
                    lo, hi = parse_offset(lo), parse_offset(hi)
                    if lo is not None and hi is not None:
                        self.ranges.append((lo, hi + 1, entry))
        self.ranges.sort()
        self.starts = [r[0] for r in self.ranges]

    def enclosing(self, addr):
        i = bisect.bisect_right(self.starts, addr) - 1
        if i >= 0 and addr < self.ranges[i][1]:
            return self.ranges[i][2]
        return None


def load_function_table():
    path = os.path.join(ROOT, "tables", "functions.csv")
    return FunctionTable(path) if os.path.isfile(path) else None


def resolve_candidate(r, off, extra_col, funcs_index, func_table):
    if func_table is not None:
        entry = func_table.enclosing(off)
        if entry is None:
            return None, None
        if entry != off:
            r = dict(r)
            r["Function Address"] = "{:x}".format(IMAGE_BASE + entry)
            r["Function Offset"] = "0x{:x}".format(entry)
            off = entry
    enrich = funcs_index.get(off)
    if enrich:
        merged = dict(enrich)
        merged[extra_col] = r.get(extra_col, "")
        return off, merged
    if func_table is not None:
        # Rows outside funcs_all still get a size, so --max-size applies to them too
        size, name = func_table.info[off]
        r = dict(r)
        r["Function Size"] = str(size)
        if not (r.get("Function Name") or "").strip():
            r["Function Name"] = name
    return off, r


def load_runtime_candidates():
    # Read the edges since the summary's callers cell is capped and can drop callers
    path = os.path.join(ROOT, "tables", "runtime_xrefs.csv")
    if not os.path.isfile(path):
        return []
    counts = {}
    names = {}
    with open(path, "r", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            # Callers in outside_function rows are raw addresses with no entry to hook
            if (row.get("kind") or "").strip() in ("out_of_module", "outside_function"):
                continue
            addr = parse_offset(row.get("caller_offset"))
            if addr is None:
                continue
            counts[addr] = counts.get(addr, 0) + to_int(row.get("runtime_count"))
            if not names.get(addr):
                names[addr] = (row.get("caller_name") or "").strip()
    rows = []
    for addr, c in counts.items():
        rows.append({
            "Function Address": "{:x}".format(IMAGE_BASE + addr),
            "Function Offset": "0x{:x}".format(addr),
            "Function Name": names[addr] or "FUN_{:x}".format(IMAGE_BASE + addr),
            "Function Symbol": "",
            "Function Demangled": "",
            "Runtime Count": str(c),
        })
    rows.sort(key=lambda r: -to_int(r.get("Runtime Count")))
    return rows


def load_hash40_candidates():
    path = os.path.join(ROOT, "tables", "hash40_loads.csv")
    if not os.path.isfile(path):
        return []
    counts = {}
    info = {}
    with open(path, "r", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            addr = parse_offset(row.get("Function Address"))
            if addr is None:
                continue
            off = addr - IMAGE_BASE if addr >= IMAGE_BASE else addr
            counts[off] = counts.get(off, 0) + 1
            if off not in info:
                info[off] = {
                    "Function Address": "{:x}".format(addr),
                    "Function Offset": "0x{:x}".format(off),
                    "Function Name": (row.get("Function Name") or "").strip(),
                    "Function Symbol": (row.get("Function Symbol") or "").strip(),
                    "Function Demangled": (row.get("Function Demangled") or "").strip(),
                }
    rows = []
    for addr, c in counts.items():
        r = dict(info[addr])
        r["Hash40 Loads"] = str(c)
        rows.append(r)
    rows.sort(key=lambda r: -to_int(r.get("Hash40 Loads")))
    return rows


def filter_candidates(rows, min_refs, max_size):
    out = []
    for row in rows:
        sym = (row.get("Function Symbol") or "").strip()
        if sym.startswith("_Z"):
            out.append(row)
            continue
        refs = to_int(row.get("Function Incoming Refs"))
        size = to_int(row.get("Function Size"))
        if refs < min_refs:
            continue
        if max_size > 0 and size > 0 and size > max_size:
            continue
        fn_name = (row.get("Function Name") or "").strip()
        callers = (row.get("Callers") or "")
        if fn_name and fn_name in callers:
            continue
        out.append(row)
    return out


def gen_one(category, top_n, min_refs, max_size, replace, sample_after, sample_every, walk_stack, max_runtime_count, global_seen, global_idents, funcs_index, func_table=None):
    no_func = 0
    if category == "hash40":
        raw = load_hash40_candidates()
        if not raw:
            print("missing tables/hash40_loads.csv")
            return False
        candidates = []
        for r in raw:
            off = parse_offset(r.get("Function Offset"))
            if off is None:
                continue
            off, row = resolve_candidate(r, off, "Hash40 Loads", funcs_index, func_table)
            if off is None:
                no_func += 1
                continue
            if off in global_seen:
                continue
            global_seen.add(off)
            candidates.append(row)
        candidates = filter_candidates(candidates, min_refs, max_size)
        candidates.sort(key=lambda r: -to_int(r.get("Hash40 Loads")))
        rows = candidates[:top_n]
    elif category == "runtime":
        # Hooking callers from a previous run's stack walks reveals one more level up the call chain
        raw = load_runtime_candidates()
        if not raw:
            print("missing tables/runtime_xrefs.csv (run ingest_call_log.py first)")
            return False
        candidates = []
        for r in raw:
            off = parse_offset(r.get("Function Offset"))
            if off is None:
                continue
            off, row = resolve_candidate(r, off, "Runtime Count", funcs_index, func_table)
            if off is None:
                no_func += 1
                continue
            if off in global_seen:
                continue
            # Skip hot fighter-side paths (X18 risk on the trampoline) when filtering for online
            rc = to_int(r.get("Runtime Count"))
            if max_runtime_count > 0 and rc > max_runtime_count:
                continue
            global_seen.add(off)
            candidates.append(row)
        candidates = filter_candidates(candidates, min_refs, max_size)
        candidates.sort(key=lambda r: -to_int(r.get("Runtime Count")))
        rows = candidates[:top_n]
    else:
        in_path = os.path.join(FUNCS_DIR, "funcs_{0}.csv".format(category))
        if not os.path.isfile(in_path):
            print("missing {0}".format(in_path))
            return False
        candidates = []
        with open(in_path, "r", encoding="utf-8") as f:
            r = csv.DictReader(f)
            for row in r:
                sym = (row.get("Function Symbol") or "").strip()
                off = parse_offset(row.get("Function Offset"))
                if not sym.startswith("_Z") and off is None:
                    continue
                if off is not None:
                    if off in global_seen:
                        continue
                    global_seen.add(off)
                candidates.append(row)
        candidates = filter_candidates(candidates, min_refs, max_size)
        candidates.sort(key=lambda r: -to_int(r.get("Function Incoming Refs")))
        rows = candidates[:top_n]

    out_path = os.path.join(OUT_DIR, "{0}.rs".format(category))
    if os.path.isfile(out_path):
        with open(out_path, "r", encoding="utf-8") as f:
            if not f.readline().startswith("// Auto-generated"):
                print("{0} is hand-edited, not overwriting it".format(out_path))
                return False
    used = global_idents
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(PRELUDE.format(src=VIRTUAL_SOURCES.get(category, "funcs/funcs_{0}.csv".format(category))))

        sym_rows = [r for r in rows if (r.get("Function Symbol") or "").startswith("_Z")]
        if sym_rows:
            f.write('extern "C" {\n')
            for row in sym_rows:
                base = row.get("Function Name") or "fn"
                base = base.split("::")[-1]
                ident = safe_ident(base, "fn")
                n = 2
                while ident in used:
                    ident = "{0}_{1}".format(ident, n)
                    n += 1
                used.add(ident)
                row["_ident"] = ident
                f.write('    #[link_name = "{0}"]\n'.format(row["Function Symbol"]))
                f.write("    fn target_{0}(x0:u64,x1:u64,x2:u64,x3:u64,x4:u64,x5:u64,x6:u64,x7:u64)->u64;\n".format(ident))
            f.write("}\n\n")

        for row in rows:
            if "_ident" in row:
                continue
            off = parse_offset(row.get("Function Offset"))
            human = pick_name(row)
            row["_human"] = human
            base = human or row.get("Function Name") or ""
            base = base.split("(")[0].split("::")[-1]
            if not base or base.startswith("FUN_"):
                base = "off_{0:x}".format(off)
            ident = safe_ident(base, "fn")
            if ident in used:
                ident = "{0}_{1:x}".format(ident, off)
            n = 2
            while ident in used:
                ident = "{0}_{1}".format(ident, n)
                n += 1
            used.add(ident)
            row["_ident"] = ident

        # Inline by default since the 4-byte atomic patch is race-safe and captures LR for dynamic xrefs.
        # The --replace flag overwrites 20 bytes of prologue to also log exit and the return value, but loses LR and races with running threads.
        # Symbol hooks always use replace since the linker resolves the entry
        for row in rows:
            ident = row["_ident"]
            sym = (row.get("Function Symbol") or "").strip()
            off = parse_offset(row.get("Function Offset"))
            row["_id"] = off if off is not None else 0
            if sym.startswith("_Z") or replace:
                if sym.startswith("_Z"):
                    f.write('#[skyline::hook(replace = target_{0})]\n'.format(ident))
                else:
                    f.write('#[skyline::hook(offset = 0x{0:x})]\n'.format(off))
                f.write("unsafe fn hook_{0}(x0:u64,x1:u64,x2:u64,x3:u64,x4:u64,x5:u64,x6:u64,x7:u64)->u64 {{\n".format(ident))
                f.write("    logger::log_enter(0x{0:x}, 0, [x0,x1,x2,x3,x4,x5,x6,x7]);\n".format(row["_id"]))
                f.write("    let r = call_original!(x0,x1,x2,x3,x4,x5,x6,x7);\n")
                f.write("    logger::log_exit(0x{0:x}, r);\n".format(row["_id"]))
                f.write("    r\n")
                f.write("}\n\n")
            else:
                f.write('#[skyline::hook(offset = 0x{0:x}, inline)]\n'.format(off))
                f.write("unsafe fn hook_{0}(ctx: &skyline::hooks::InlineCtx) {{\n".format(ident))
                if sample_every > 1:
                    f.write("    static N: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);\n")
                    f.write("    let n = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);\n")
                    f.write("    if n >= {0} && n % {1} != 0 {{ return; }}\n".format(sample_after, sample_every))
                if walk_stack:
                    f.write("    logger::log_enter_walk(0x{0:x}, ctx.registers[30].x(), ctx.registers[29].x(), [\n".format(row["_id"]))
                else:
                    f.write("    logger::log_enter(0x{0:x}, ctx.registers[30].x(), [\n".format(row["_id"]))
                for i in range(8):
                    f.write("        ctx.registers[{0}].x(),\n".format(i))
                f.write("    ]);\n")
                f.write("}\n\n")

        f.write("pub fn install() {\n")
        f.write("    skyline::install_hooks!(\n")
        for row in rows:
            f.write("        hook_{0},\n".format(row["_ident"]))
        f.write("    );\n")
        f.write("}\n")
    print("wrote {0} ({1} hooks)".format(out_path, len(rows)))
    if no_func:
        print("skipped {0} candidates outside every Ghidra function".format(no_func))

    catalog_path = os.path.join(SNIFFER_ROOT, "call_sniffer_funcs_{0}.csv".format(category))
    with open(catalog_path, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow(["Ident", "Function Address", "Function Offset", "Hint Name", "Function Name", "Function Symbol", "Function Demangled", "Function Signature"])
        for row in rows:
            w.writerow([row["_ident"], row.get("Function Address", ""), row.get("Function Offset", ""),
                        row.get("_human", ""),
                        row.get("Function Name", ""), row.get("Function Symbol", ""),
                        row.get("Function Demangled", ""), row.get("Function Signature", "")])
    print("wrote {0}".format(catalog_path))
    return True


def main():
    if len(sys.argv) < 2:
        print("usage: generate_hooks.py <category> [...] [--top=N] [--min-refs=N] [--max-size=N] [--replace] [--no-walk] [--sample-after=N --sample-every=M] [--exclude=0x...] [--max-runtime-count=N]")
        sys.exit(1)
    top_n = 50
    min_refs = 0
    max_size = 2000
    replace = False
    sample_after = 32
    sample_every = 1
    walk_stack = True
    max_runtime_count = 0
    exclude = set()
    cats = []
    for a in sys.argv[1:]:
        if a.startswith("--top="):
            top_n = int(a.split("=", 1)[1])
        elif a.startswith("--min-refs="):
            min_refs = int(a.split("=", 1)[1])
        elif a.startswith("--max-size="):
            max_size = int(a.split("=", 1)[1])
        elif a.startswith("--sample-after="):
            sample_after = int(a.split("=", 1)[1])
        elif a.startswith("--sample-every="):
            sample_every = int(a.split("=", 1)[1])
        elif a.startswith("--max-runtime-count="):
            max_runtime_count = int(a.split("=", 1)[1])
        elif a.startswith("--exclude="):
            for v in a.split("=", 1)[1].split(","):
                off = parse_offset(v)
                if off is not None:
                    exclude.add(off)
        elif a == "--replace":
            replace = True
        elif a == "--no-walk":
            walk_stack = False
        else:
            cats.append(a)
    if not os.path.isdir(OUT_DIR):
        os.makedirs(OUT_DIR)
    ok = True
    global_seen = set(exclude)
    global_idents = set()   # Idents must stay unique across category modules since skyline::hook makes hook_xxx #[no_mangle]
    funcs_index = load_funcs_all_index()
    func_table = load_function_table()
    for cat in cats:
        if not gen_one(cat, top_n, min_refs, max_size, replace, sample_after, sample_every, walk_stack, max_runtime_count, global_seen, global_idents, funcs_index, func_table):
            ok = False
    if not ok:
        sys.exit(1)
    print("\nremember to add 'mod {0};' lines and the install() calls in ../ssbu-call-sniffer/src/hooks/mod.rs".format(cats[0] if cats else "<category>"))


if __name__ == "__main__":
    main()
